mapper.select:
SELECT COUNT(1)
FROM sku
WHERE product_id = #{productId}
  AND status = #{status}

mapper.update:
UPDATE sku
name = #{name}, price = #{price}, status = #{status}, updated_at = CURRENT_TIMESTAMP
WHERE id = #{id}

UPDATE sku
SET status = #{status},
    updated_at = CURRENT_TIMESTAMP
WHERE product_id = #{productId}
  AND status <> #{status}

mapper.select:
SELECT product_id AS productId, MIN(price) AS minPrice, COUNT(*) AS skuCount FROM sku WHERE status <> 2 AND product_id IN
#{pid}
GROUP BY product_id
